<div class="narrow wide-form"><a class="back-link" href="<?= e(url('tickets')) ?>"><?= icon('chevron-left') ?>Voltar para Chamados</a><section class="card card-body"><div class="row-title"><span class="eyebrow">Chamado #<?= str_pad((string)$record['id'],4,'0',STR_PAD_LEFT) ?></span><?= badge($record['status']) ?></div><h2><?= e($record['subject']) ?></h2><p class="description preserve-lines"><?= e($record['description']) ?></p><dl class="detail-list"><?php foreach(['Solicitante'=>$record['user_name'],'E-mail'=>$record['user_email'],'Categoria'=>$record['category_name'],'Prioridade'=>$record['priority'],'Destinatário / responsável'=>$record['assignee_name']??'Não atribuído','Criado em'=>date('d/m/Y H:i',strtotime($record['created_at'])),'Atualizado em'=>date('d/m/Y H:i',strtotime($record['updated_at']))] as $label=>$value): ?><div><dt><?= e($label) ?></dt><dd><?= e($value) ?></dd></div><?php endforeach; ?></dl><?php if($canManage): ?><div class="form-actions"><?php delete_button('tickets',(int)$record['id'],$record['subject']); ?><a class="button" href="<?= e(url('tickets',['action'=>'edit','id'=>$record['id']])) ?>"><?= icon('pencil') ?>Editar chamado</a></div><?php endif; ?></section></div>
